// Forecast/PM2.5/UV all update far less often (~every 30min-1hr) than the
// live temp/humidity readings above, so cache them in workflow static data
// and only re-fetch once the cache is stale. This cuts data.gov.sg API
// calls roughly 6x since this workflow still runs every 5 minutes.
const cfg = $('Config (edit per location)').item.json;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const CACHE_MS = 30 * 60 * 1000;

if (staticData.slowWeather && (now - staticData.slowWeather.cachedAt) < CACHE_MS) {
  return [{ json: staticData.slowWeather.data }];
}

const headers = { 'x-api-key': cfg.DATA_GOV_SG_API_KEY };

const sgDate = new Date(now + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);

const [forecastResp, pm25Resp, moonResp] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: 'https://api-open.data.gov.sg/v2/real-time/api/two-hr-forecast', headers, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: 'https://api-open.data.gov.sg/v2/real-time/api/pm25', headers, json: true }),
  // USNO (US Naval Observatory) - authoritative, free, no API key - gives
  // the current named moon phase (curphase) plus today's sun rise/set
  // times (sundata, SG local time), so no local astronomical calc is needed.
  this.helpers.httpRequest({ method: 'GET', url: `https://aa.usno.navy.mil/api/rstt/oneday?date=${sgDate}&coords=${cfg.HOME_LAT},${cfg.HOME_LON}&tz=8`, json: true }),
]);

const data = { forecast: forecastResp.data, pm25: pm25Resp.data, astro: moonResp.properties && moonResp.properties.data };
staticData.slowWeather = { cachedAt: now, data };

return [{ json: data }];

// Both the sensor readings and the forecast/PM2.5 come from a network of
// stations/areas/regions, not a single point - pick whichever is
// physically closest to home for each.
const cfg = $('Config (edit per location)').item.json;
const tempResp = $('Fetch Air Temperature (data.gov.sg)').item.json.data;
const humResp = $('Fetch Relative Humidity (data.gov.sg)').item.json.data;
const slow = $input.first().json;
const forecastResp = slow.forecast;
const pm25Resp = slow.pm25;

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function nearestReading(resp) {
  const stationsById = Object.fromEntries(resp.stations.map(s => [s.id, s.location]));
  const readings = resp.readings[0].data;
  const withDist = readings
    .filter(r => stationsById[r.stationId])
    .map(r => ({
      value: r.value,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, stationsById[r.stationId].latitude, stationsById[r.stationId].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].value;
}

function nearestForecast(resp) {
  const areasByName = Object.fromEntries(resp.area_metadata.map(a => [a.name, a.label_location]));
  const forecasts = resp.items[0].forecasts;
  const withDist = forecasts
    .filter(f => areasByName[f.area])
    .map(f => ({
      forecast: f.forecast,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, areasByName[f.area].latitude, areasByName[f.area].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return { forecast: withDist[0].forecast, validPeriodText: resp.items[0].valid_period.text };
}

function nearestPM25(resp) {
  const regionsByName = Object.fromEntries(resp.regionMetadata.map(r => [r.name, r.labelLocation]));
  const readings = resp.items[0].readings.pm25_one_hourly;
  const withDist = Object.entries(readings)
    .filter(([name]) => regionsByName[name])
    .map(([name, value]) => ({
      value,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, regionsByName[name].latitude, regionsByName[name].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].value;
}

// Compacts a data.gov.sg valid_period string like
// "5.00 pm to 7.00 pm" into "5-7PM" for the small clock display.
function compactPeriod(text) {
  const m = text.match(/(\d{1,2})[.:]\d{2}\s*(am|pm)\s*to\s*(\d{1,2})[.:]\d{2}\s*(am|pm)/i);
  if (!m) return text.toUpperCase();
  const [, h1, ap1, h2, ap2] = m;
  return ap1.toLowerCase() === ap2.toLowerCase()
    ? `${h1}-${h2}${ap2.toUpperCase()}`
    : `${h1}${ap1.toUpperCase()}-${h2}${ap2.toUpperCase()}`;
}

// Maps data.gov.sg 2-hour forecast strings to AWTRIX icon IDs - added to
// the clock manually via its web UI (Icons -> Fetch from LaMetric gallery
// by ID -> Save to AWTRIX), not uploaded by this workflow or any script.
// See README for the full list of IDs this workflow needs. Picked to match
// https://flows.blueforcer.de/flow/QZ0sO0JQb7ut, extended to cover the
// extra conditions data.gov.sg reports that open-meteo doesn't. Singapore
// never reports snow, so unlike that flow's source there's no snow icon.
const FORECAST_ICON = {
  'Fair': '53386',
  'Fair (Day)': '53386',
  'Fair (Night)': '53386',
  'Fair and Warm': '53386',
  'Partly Cloudy': '2286',
  'Partly Cloudy (Day)': '2286',
  'Partly Cloudy (Night)': '2286',
  'Cloudy': '53384',
  'Hazy': '17055',
  'Slightly Hazy': '17055',
  'Windy': '2286',
  'Mist': '17055',
  'Fog': '17055',
  'Light Rain': '2720',
  'Moderate Rain': '2720',
  'Heavy Rain': '49300',
  'Passing Showers': '2720',
  'Light Showers': '2720',
  'Showers': '49300',
  'Heavy Showers': '49300',
  'Thundery Showers': '29839',
  'Heavy Thundery Showers': '29839',
  'Heavy Thundery Showers with Gusty Winds': '29839'
};
const DEFAULT_ICON = '36637';

// Clear sky at night shows the current moon phase instead of the sun icon
// used for daytime 'Fair'. Named phase comes from USNO (see fetch node);
// this map covers the 8 primary/intermediate phases USNO's curphase
// returns, icon IDs from the LaMetric gallery (added to the clock
// manually, see README).
const MOON_PHASE_ICON = {
  'New Moon': '2318',
  'Waxing Crescent': '2317',
  'First Quarter': '2316',
  'Waxing Gibbous': '2315',
  'Full Moon': '2314',
  'Waning Gibbous': '2319',
  'Last Quarter': '2320',
  'Waning Crescent': '2321',
};

// Local synodic-month fallback, used only if USNO is unreachable or
// returns a phase name outside the map above.
function moonPhaseIconFallback(date) {
  const synodicMonthDays = 29.53058867;
  const knownNewMoonUtc = Date.UTC(2000, 0, 6, 18, 14, 0);
  const daysSince = (date.getTime() - knownNewMoonUtc) / 86400000;
  let phase = (daysSince % synodicMonthDays) / synodicMonthDays;
  if (phase < 0) phase += 1;
  const icons = ['2318', '2317', '2316', '2315', '2314', '2319', '2320', '2321'];
  const bucket = Math.floor(((phase + 1 / 16) % 1) * 8);
  return icons[bucket];
}

function moonPhaseIcon(astroData, date) {
  const name = astroData && astroData.curphase;
  if (name && MOON_PHASE_ICON[name]) return MOON_PHASE_ICON[name];
  return moonPhaseIconFallback(date);
}

// Night variants of the cloud conditions. data.gov.sg tags dark-hours
// forecasts with a '(Night)' suffix ('Partly Cloudy (Night)' etc.);
// keyed here on the base condition with that suffix stripped. Icon IDs
// from the LaMetric gallery, added to the clock manually (see README).
// The clock's icon partition is often full, so any value left '' just
// keeps the daytime icon rather than rendering a blank slot.
const NIGHT_ICON = {
  'Partly Cloudy': '43737', // moon + cloud; '' -> falls back to day '2286'
};
// Other night icons picked but unused: data.gov.sg only ever suffixes
// 'Fair' and 'Partly Cloudy' with '(Day)'/'(Night)', so rain / thundery
// conditions never arrive tagged as night. Add a key above (and the icon
// to the clock) only if that changes: moon + rain 43738, heavier rain
// 43739, drizzle 43747, thunderstorm 43748.

// Clear sky at night shows the actual moon phase; other '(Night)'
// conditions use NIGHT_ICON if a night icon has been added, else the
// normal (daytime) FORECAST_ICON entry.
function pickIcon(text) {
  if (/\(Night\)\s*$/i.test(text)) {
    const base = text.replace(/\s*\(Night\)\s*$/i, '').trim();
    if (base === 'Fair' || base === 'Fair and Warm') return moonPhaseIcon(slow.astro, new Date());
    if (NIGHT_ICON[base]) return NIGHT_ICON[base];
  }
  return FORECAST_ICON[text] || DEFAULT_ICON;
}

// data.gov.sg's 2hr-forecast is really "the forecast for the upcoming ~2hr
// window", so it doubles as both "current conditions" and "next" - there's
// no finer-grained hourly forecast available from the API.
const { forecast: forecastText, validPeriodText } = nearestForecast(forecastResp);
const forecastIcon = pickIcon(forecastText);

const temp = Math.round(nearestReading(tempResp));
const hum = Math.round(nearestReading(humResp));
const weatherPayload = { text: `${temp}°C ${hum}%`, icon: forecastIcon, durationMs: 8000, textCase: 'upper' };

const forecastPayload = { text: `FORECAST ${compactPeriod(validPeriodText)}`, icon: forecastIcon, durationMs: 8000, textCase: 'upper' };

// AWTRIX's "AQI" icon set - 12 severity tiers, also added manually via the
// clock's web UI (see README). Bands the raw PM2.5 reading (ug/m3) against
// each tier's icon.
const AQI_ICON_BANDS = [
  { max: 25, icon: '39706' },
  { max: 40, icon: '39709' },
  { max: 60, icon: '39710' },
  { max: 90, icon: '39711' },
  { max: 110, icon: '39712' },
  { max: 140, icon: '39713' },
  { max: 160, icon: '39714' },
  { max: 190, icon: '39715' },
  { max: 210, icon: '39716' },
  { max: 290, icon: '39717' },
  { max: 310, icon: '39718' },
];
const AQI_ICON_OVER_MAX = '39719';

function aqiIconFor(pm25) {
  const band = AQI_ICON_BANDS.find(b => pm25 <= b.max);
  return band ? band.icon : AQI_ICON_OVER_MAX;
}

const pm25 = Math.round(nearestPM25(pm25Resp));
const aqIcon = aqiIconFor(pm25);
const aqiPayload = { text: `PM2.5 ${pm25}`, icon: aqIcon, durationMs: 8000, textCase: 'upper' };

// Sunrise / sunset - times come from the same USNO response as the moon
// phase (sundata, "HH:MM" in SG time), with fixed SG fallbacks if USNO is
// unreachable (Singapore's rise/set barely move across the year). The
// `sun` app is only pushed within +/-2h of the next event; its text
// shows the exact event time from USNO, e.g. "RISE 7:01AM" / "SET
// 7:10PM". The `moon` app is only pushed at night (after sunset /
// before sunrise). Both carry a short `lifetimeMs` so the clock removes
// them a few minutes after their window closes and we stop re-pushing -
// the always-on apps (weather / weather_forecast / aqi) have no lifetimeMs
// and just get re-pushed every run.
function sunEventMinutes(astro, phen) {
  const hit = ((astro && astro.sundata) || []).find(p => p.phen === phen);
  if (!hit) return null;
  const [h, m] = hit.time.split(':').map(Number);
  return h * 60 + m;
}

// Formats an SG minutes-past-midnight value as an exact 12-hour clock
// time like "7:01AM" / "7:10PM" for the small clock display.
function sunTime(mins) {
  const t = ((mins % 1440) + 1440) % 1440;
  const h24 = Math.floor(t / 60);
  const mm = t % 60;
  const ap = h24 < 12 ? 'AM' : 'PM';
  const h12 = h24 % 12 || 12;
  return `${h12}:${String(mm).padStart(2, '0')}${ap}`;
}

const sgNow = new Date(Date.now() + 8 * 60 * 60 * 1000);
const sgNowMin = sgNow.getUTCHours() * 60 + sgNow.getUTCMinutes();
const sunriseMin = sunEventMinutes(slow.astro, 'Rise') ?? 421;  // 07:01 SG fallback
const sunsetMin = sunEventMinutes(slow.astro, 'Set') ?? 1150;   // 19:10 SG fallback

// SG for/sunset sit far from midnight, so a plain +/-2h check needs
// no day-wrap handling. lifetimeMs 360000 (360s) > the 300s push interval, so one
// missed run won't flap the app, but it clears ~6min after its window.
const SUN_GATE_MIN = 120;

let sunPayload = null;
if (Math.abs(sgNowMin - sunriseMin) <= SUN_GATE_MIN) {
  sunPayload = { text: `RISE ${sunTime(sunriseMin)}`, icon: '22588', durationMs: 8000, textCase: 'upper', lifetimeMs: 360000 };
} else if (Math.abs(sgNowMin - sunsetMin) <= SUN_GATE_MIN) {
  sunPayload = { text: `SET ${sunTime(sunsetMin)}`, icon: '12061', durationMs: 8000, textCase: 'upper', lifetimeMs: 360000 };
}

// Moon phase app - night only (after sunset / before sunrise). Icon is the
// current phase; text is the phase name + illuminated fraction, e.g.
// "WANING GIBBOUS 99%". (The same icon is still used as the weather icon
// on a clear night, driven by the forecast string, independently of this.)
let moonPayload = null;
if (sgNowMin >= sunsetMin || sgNowMin < sunriseMin) {
  const moonPhaseName = (slow.astro && (slow.astro.curphase || (slow.astro.closestphase && slow.astro.closestphase.phase))) || '';
  const moonIllum = (slow.astro && slow.astro.fracillum) || '';
  moonPayload = {
    text: `${moonPhaseName} ${moonIllum}`.trim() || 'MOON',
    icon: moonPhaseIcon(slow.astro, new Date()),
    durationMs: 8000,
    textCase: 'upper',
    lifetimeMs: 360000,
  };
}

const items = [
  { json: { app: 'current_weather', payload: weatherPayload } },
  { json: { app: 'weather_forecast', payload: forecastPayload } },
  { json: { app: 'aqi', payload: aqiPayload } },
];
if (sunPayload) items.push({ json: { app: 'sunrise_sunset', payload: sunPayload } });
if (moonPayload) items.push({ json: { app: 'moon_phase', payload: moonPayload } });
return items;

// TC002 runs AWTRIX NG (1.2.2+), so it takes the same pushed-app API as the
// TC001 (PUT /api/v1/apps/pushed/<app>), but its panel is 52x16. A plain
// text/icon payload would be drawn at double size on a 26x8 grid, so this
// builds a `layout` instead, which uses all 52x16 pixels: the 16x16 icon on
// the left, two text lines in boxes to its right. Text that does not fit
// its box scrolls through it by itself.
// Icons: the AWTRIX NG payloads above reference LaMetric icon IDs stored on
// the TC001. Rather than also uploading them to the TC002, the same icons
// travel inline as 16x16 GIF data URLs. Each is the icon's native 8x8 GIF
// (developer.lametric.com/content/apps/icon_thumbs/<id>.gif) 2x
// nearest-neighbor upscaled, flattened onto black, per-frame delays kept.
// IDs whose LaMetric icon has no animation (53386 Fair, the 39706-39719 AQI
// ramp, the 2314-2321 moon phases) stay single-frame.
const ICON16_B64 = {"12061": "", "17055": "R0lGODlhEAAQAIEAAKymnAAAAAAAAAAAACH/C05FVFNDQVBFMi4wAwEAAAAh+QQEMgAAACwAAAAAEAAQAAAILwADCBxIsKDBgwgBKFzI0CDDhwAQSpx4EKJAiBgjBshIsSPFjAodgvRIsqTJiQEBACH5BAQyAAAALAIAAgAMAAoAgaymnAAAAAAAAAAAAAgjAAEIHEgwQACCCAEYXMiwoUOHCQ0mLHhw4MOLGCVOFKhxY0AAOw==", "22588": "", "2286": "", "2314": "R0lGODdhEAAQAIEAAPDw8NbW1ra2tgAAACwAAAAAEAAQAEAIWQAHCBwQoKDBggMJBgAAQIAAhhAhHiwY0aHDgwIPOmSIceDBiB0pNnw4EuTEiAwvGkw4cWVCjy0DvFQokqPLjxAtCmiZkuRGiQZ7ogSKs+LOmwZ/dmQZM2FAADs=", "2315": "R0lGODdhEAAQAIIAAPDw8NbW1szMzDY2NgAAAAAAAAAAAAAAACwAAAAAEAAQAEAIXwAJCCQQoGCAAQgHDCQYAAAAAQIcSgSQcIDBhhIhQqwo8CJEhxwHXpwYsqDDjw8jUkw4cmLKkB0NwlzIsODMmCYlljQ4UaOAijlRogSKESVJljxdbkyIM8BQpjQvzgwIADs=", "2316": "R0lGODdhEAAQAIIAAPDw8NbW1s7OzjU1NR0dHQAAAAAAAAAAACwAAAAAEAAQAEAIZgALCCwQoGCAAQgHDCQYAAAAAQIcJpw4wGBDhwAIaCQwUaBFiBQVDrQokaLHixAdagxJEiPClQkXWuy4cKRBmjINlqTZUuXGiQUdpszIkWLQhxEBhETYU+kAmAhPFgRpsubMmAMDAgA7", "2317": "R0lGODdhEAAQAIIAAPDw8NbW1ioqKhwcHAAAAAAAAAAAAAAAACwAAAAAEAAQAEAIXAAJCCQQoGAAAQgFDCQYAACAAQMSSkxo8GBCiBAlCqyYceLCihMTbmz4MKKAjhJBTkSpcKBKhAs/GtQY86VHhgUlYjSJsKDDjix7kgw60SZCliMLEo2J0yLMgQEBADs=", "2318": "R0lGODdhEAAQAIEAACoqKhwcHAAAAAAAACwAAAAAEAAQAEAISAAFCBQAoKDBggMJGgwQ4KDDhwsZNjQo8CDDhwkhOqwYseBFjRA/IhyoMWFGiCYVggTA8aHEiS4nigwJcyXNgy0BzBx5EuPAgAA7", "2319": "R0lGODdhEAAQAIIAAPDw8NbW1sLCwjMzMwAAAAAAAAAAAAAAACwAAAAAEAAQAEAIYgAJCCQwoOCAAAgDDCRoUIAAABAjQkRocIBEhw4TKmRY0OHEhAsrIvyIUGBFjwBQfqwoEWJGkANFwlxo0qBGmhwPBiC5kWVEjAI0nnyYkujKhkZbUjTYsujNnCifhrQ5k0BAADs=", "2320": "R0lGODdhEAAQAIIAAPDw8NbW1svLyzMzMxkZGQAAAAAAAAAAACwAAAAAEAAQAEAIZgALCCwwoOCAAAgDDCRokACBggAiSkRosOIAARgFJFTIsGLEjQstDviYUGBFhwUxSgRAUeRIABhBDqwoc6FJgzVnWiSJ8KbIjBoTnnx4UcDKlgVRvjwawOXLmCU7GuTJMSTOqAIDAgA7", "2321": "R0lGODdhEAAQAIIAAPDw8NbW1jMzMxoaGhkZGQAAAAAAAAAAACwAAAAAEAAQAEAIXQALCCwgoKCAAAgDDCRokAABgwYBAEAIEeKAiwMSKmRY8WDChR0LahQI0WHBiwUlUgx5MuPHgRBHLoRpUCbIkDJZYnS5sqBJASgFqAxQ8mHFoSxb5sT58qbIpgUCAgA7", "2720": "", "29839": "", "36637": "", "39706": "R0lGODdhEAAQAIEAABn8ACKqEwAAAAAAACwAAAAAEAAQAEAINgAFCBQQIACAgwgTKlyosCBDhgIfLowosWJFhxYPDiRoUOJGjA8pZgSZsaTJhCQrirT4sePDgAA7", "39709": "R0lGODdhEAAQAIEAABn8AAAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "39710": "R0lGODdhEAAQAIEAAPzoABn8AAAAAAAAACwAAAAAEAAQAEAINgADCBwoEIDBgwYJEkSIUOFAhgcdFoQIQGIAihUlYrS4USNFjh89QgQ5UiRDkidNNlQZkaXBgAA7", "39711": "R0lGODdhEAAQAIEAAPzoAAAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "39712": "R0lGODdhEAAQAIEAAPzoAPylAAAAAAAAACwAAAAAEAAQAEAINgABCBwoMIDBgwYJEkSIUOFAhgcdFoQYQCIAihUlYrS4USNFjh89QgQ5UiRDkidNNlQZkaXBgAA7", "39713": "R0lGODdhEAAQAIEAAPylAAAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "39714": "R0lGODdhEAAQAIEAAPylAPwAAAAAAAAAACwAAAAAEAAQAEAINgABCBwoMIDBgwYJEkSIUOFAhgcdFoQYQCIAihUlYrS4USNFjh89QgQ5UiRDkidNNlQZkaXBgAA7", "39715": "R0lGODdhEAAQAIEAAPwAAAAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "39716": "R0lGODdhEAAQAIEAAPwAAKoAFwAAAAAAACwAAAAAEAAQAEAINgABCBwoMIDBgwYJEkSIUOFAhgcdFoQYQCIAihUlYrS4USNFjh89QgQ5UiRDkidNNlQZkaXBgAA7", "39717": "R0lGODdhEAAQAIEAAKoAFwAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "39718": "R0lGODdhEAAQAIEAAKoAF3UAOAAAAAAAACwAAAAAEAAQAEAINgABCBwoMIDBgwYJEkSIUOFAhgcdFoQYQCIAihUlYrS4USNFjh89QgQ5UiRDkidNNlQZkaXBgAA7", "39719": "R0lGODdhEAAQAIEAAHUAOAAAAAAAAAAAACwAAAAAEAAQAEAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBADs=", "43737": "", "49300": "", "53384": "", "53386": "R0lGODdhEAAQAIEAAP/7AMC9AFdWAAAAACwAAAAAEAAQAEAIVwAHCBwgQECAgwEKDhxwEIDDhxAdHizYMKLEhAIEIgwAcePCjR0RauRoMeJEgyQtnlxIEaHChQNbroQJ8qFHgihLAjhZUefFnj55pjSJcSTQmyxRzhQYEAA7"};

// Runs in "Run Once for All Items" mode - iterate $input.all() and return
// one output item per input item.
//
// 30s per app on the TC002 (overrides the upstream durationMs, which stays
// 8000 for the TC001). lifetimeMs is copied from upstream, so the
// sunrise_sunset / moon_phase cards expire on their own once Build Payloads
// stops emitting them, same as on the TC001.
const TC002_DURATION_MS = 30000;

const ICON_BOX = [0, 0, 16, 16];
const LINE1_BOX = [18, 0, 34, 8];
const LINE2_BOX = [18, 8, 34, 8];

function buildOne(item) {
  const iconId = item.payload && item.payload.icon;
  const content = String((item.payload && item.payload.text) || '').toUpperCase();
  const icon = iconId && ICON16_B64[iconId];

  let line1, line2;
  if (item.app === 'current_weather') {
    // Source text is "29°C 75%". Labelled because the two bare numbers on
    // their own are ambiguous (which is temp, which humidity).
    const m = content.match(/^(\S+)\s+(\S+)$/);
    line1 = m ? `TMP ${m[1]}` : content;
    line2 = m ? `HUM ${m[2]}` : '';
  } else {
    // Last word on line 2, the rest on line 1: "FORECAST 5-7PM" ->
    // "FORECAST"/"5-7PM", "PM2.5 12" -> "PM2.5"/"12", "RISE 7:01AM" ->
    // "RISE"/"7:01AM", "WANING GIBBOUS 99%" -> "WANING GIBBOUS"/"99%".
    const words = content.split(' ').filter(Boolean);
    line1 = words.length > 1 ? words.slice(0, -1).join(' ') : (words[0] || '');
    line2 = words.length > 1 ? words[words.length - 1] : '';
  }

  const regions = [];
  if (icon) {
    regions.push({ id: 'icon', box: ICON_BOX, icon: `data:image/gif;base64,${icon}` });
    regions.push({ id: 'line1', box: LINE1_BOX, text: line1, color: '#FFFFFF', align: 'start' });
    if (line2) regions.push({ id: 'line2', box: LINE2_BOX, text: line2, color: '#3EE08A', align: 'start' });
  } else {
    regions.push({ id: 'text', box: [0, 0, 52, 16], text: content, color: '#FFFFFF' });
  }

  const tc002Payload = { durationMs: TC002_DURATION_MS, layout: { version: 1, regions } };
  if (item.payload && item.payload.lifetimeMs) tc002Payload.lifetimeMs = item.payload.lifetimeMs;

  return { json: { app: item.app, tc002Payload } };
}

return $input.all().map((entry, i) => {
  const out = buildOne(entry.json);
  out.pairedItem = { item: i };
  return out;
});
